#!/usr/bin/env python3
"""Reensambla o HTML único de distribución. Uso: python3 build.py"""
import pathlib
ROOT = pathlib.Path(__file__).parent
FILES = ['config.js', '00-preambulo.js', '01-nucleo-datos.js', '01b-assets.js', '02-pvp-lobby.js', '03-pvp-sync.js', '04-progresion.js', '05-mapa-camara-neboa.js', '06-audio-voces.js', '07-terreo-batalla.js', '08-social-narrativa.js', '09-economia-combate.js', '10-estructuras.js', '11-retratos-ui.js', '12-debrief-hangar.js', '99-boot.js']
css = (ROOT/'css/style.css').read_text()
js = '\n'.join((ROOT/'js'/f).read_text() for f in FILES)
head = '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>TUERCA — v0.37</title>'
body = '</head>\n<body>\n<h1>■ TUERCA <span id="vHangar" style="font-size:12px; color:#7fdc7f; letter-spacing:1px;"></span></h1>\n<div class="sub">V0.4 · TERRENO POR CELDAS · AUTOTILING GEOMÉTRICO</div>\n\n<!-- ===================== HANGAR ===================== -->\n<div id="hangar" class="scr">\n  <h2>// Hangar — Roster persistente <span id="chatarraDisplay" style="float:right; font-size:14px; color:#c8a86a;"></span></h2>\n  <div id="rosterList" class="small">Cargando roster…</div>\n  <div class="row">\n    <button id="btnStart">▶ Iniciar operación</button>\n    <button id="btnOnline" style="color:#7fdc7f; border-color:#7fdc7f;" title="Crea unha sala ou únete á dun rival. O creador xoga como AZUL; o convidado como VERMELLO. Cada quen co seu roster.">🌐 DUELO ONLINE</button>\n    <button id="btnLado" style="color:#4f8aff; border-color:#4f8aff;" title="Escolle a facción coa que despregas. A IA leva a outra. (Alicerce do modo 2 xogadores)">⚑ FACCIÓN: AZUL</button>\n    <button id="btnCrisol" style="color:#e8c060; border-color:#8a6a20;" title="Programa de Validación de Durabilidade de ÓPTIMA: 5 oleadas de brigadas grises contra o teu escuadrón. Todo o gañado (skills, ops, alcumes, pezas) volve contigo á campaña. Os datos doen.">⚒ O CRISOL (supervivencia)</button>\n    <button id="btnMemorial">Memorial de caídos</button>\n    <button id="btnDespiece" style="color:#c8a86a;">⚙ Despiece</button>\n    <button id="btnCantina" title="O escuadrón de charla entre operacións. Podes invitar a unha rolda (+2 confianza a todos).">🍺 Cantina</button>\n    <button id="btnCronica" title="O xogo escribe a historia da túa guerra: escuadrón, caídos, vínculos, pezas, VOLT. Descárgase como .md">📜 Crónica</button>\n    <button id="btnExport" title="Descarga a partida enteira como JSON — roster, pezas, vínculos, campaña. O localStorage é fráxil; isto non.">💾 Exportar</button>\n    <button id="btnImport" title="Carga unha partida exportada (substitúe a actual)">📂 Importar</button>\n    <input type="file" id="importFile" accept=".json,application/json" style="display:none;">\n    <button id="btnWipe">Borrar todos los datos</button>\n  </div>\n  <div id="memorial" style="display:none; margin-top:12px;" class="small"></div>\n  <p class="small" style="margin-top:14px;">\n    Selecciona hasta 3 veteranos para desplegar.<br>\n    CONTROLES: arrastra para seleccionar · clic para mover/atacar · doble clic en una unidad para seleccionar todas las del mismo tipo cercanas · teclas 1/2/3 o botones para producir.<br>\n    OBJETIVO: destruye el HQ rojo. Captura sectores (○) para producir más rápido.<br>\n    NUEVO en v0.3: enemigos que sobrevivan a una operación pueden VOLVER en las siguientes (marca naranja). Captura el RADAR CENTRAL para que se anuncien al detectarlos. Si el enemigo controla el radar, su IA conoce a tus veteranos y reacciona: pesados los priorizan, ligeros los evitan, engineers enemigos huyen para reagruparse.\n  </p>\n</div>\n\n<!-- ===================== BATALLA ===================== -->\n<div id="battle" style="display:none; width:100%; max-width:1260px;">\n  <div id="battleLayout">\n    <div id="wrap"><canvas id="cv" width="960" height="540"></canvas></div>\n    <div id="sidePanel"><div class="small">— Sin unidad seleccionada —</div></div>\n  </div>\n  <div id="hud">\n    <div id="prodbar" style="display:flex; gap:8px; flex-wrap:wrap;">\n      <button id="p0">[1] GRUNT</button>\n      <button id="p1">[2] HEAVY</button>\n      <button id="p2">[3] ENGINEER</button>\n      <button id="p3">[4] SNIPER</button>\n      <button id="p4" style="color:#c8a86a;">[5] TANQUE 40⚙</button>\n      <button id="p5">[6] BOMBARDERO</button>\n      <button id="p6" style="color:#c8a86a;">[7] TORRETA 45⚙</button>\n      <button id="pMuro" style="display:none; color:#c8a86a; border-color:#c8a86a;" title="O Engineer seleccionado camiña ao punto e constrúe o muro in situ (~4s exposto)">[8] MURO 10⚙ ⌂</button>\n      <span id="prodinfo"></span>\n      <span id="forminfo" style="padding:2px 8px; border:1px solid var(--phos-dim); font-size:11px;" title="Tecla F para alternar formación"></span>\n      <span id="radarinfo" style="margin-left:auto; padding:2px 8px; border:1px solid var(--phos-dim); font-size:11px;"></span>\n    </div>\n    <button id="btnAbort" style="margin-left:auto;">Abortar misión</button>\n  </div>\n  <div id="radio"><div class="line small">— Canal de radio abierto —</div></div>\n</div>\n\n<!-- ===================== DEBRIEF ===================== -->\n<div id="debrief" class="scr" style="display:none;">\n  <h2 id="dbTitle">// Informe de operación</h2>\n  <div id="dbBody" class="small"></div>\n  <div class="row"><button id="btnBack">Volver al hangar</button></div>\n</div>\n\n<!-- ===================== BRIEFING (v0.11) ===================== -->\n<div id="briefing" class="scr" style="display:none;">\n  <h2 id="brTitle">// Briefing — Operación</h2>\n  <div id="brBody" style="display:flex; align-items:flex-start; gap:24px; margin:32px 0; min-height:180px;">\n    <canvas id="brPortrait" width="96" height="96" style="image-rendering:pixelated; border:1px solid var(--phos-dim); background:#0a0a0a; flex-shrink:0; width:96px; height:96px;"></canvas>\n    <div style="flex:1; min-width:0;">\n      <div id="brName" style="font-size:22px; color:var(--phos); letter-spacing:1px; margin-bottom:4px;"></div>\n      <div id="brMeta" class="small" style="color:#888; margin-bottom:20px;"></div>\n      <div id="brFrase" style="font-size:17px; font-style:italic; line-height:1.5; padding:14px 18px; border-left:3px solid var(--phos); background:#1a1a1a; min-height:60px;"></div>\n    </div>\n  </div>\n  <div class="row" style="justify-content:space-between; align-items:center;">\n    <span id="brProgress" class="small" style="color:#888;"></span>\n    <span class="small" style="color:#888;">[ Espazo / Enter para continuar ]</span>\n    <button id="brNext">SEGUINTE ►</button>\n  </div>\n</div>\n\n<!-- ===================== MODAL BIOGRAFÍA ===================== -->\n<div id="bioModal">\n  <div class="inner">\n    <h2 id="bioTitle"></h2>\n    <div id="bioBody"></div>\n    <div class="row"><button id="btnBioClose">Cerrar</button></div>\n  </div>\n</div>\n'
tail = '</body>\n</html>\n'
html = head + '\n<style>\n' + css + '</style>\n' + body + '\n<script>\n' + js + '\n</script>\n' + tail + '\n'
out = ROOT/'dist/tuerca.html'
out.write_text(html)
print(f'OK -> {out} ({len(html)//1024} KB)')
